  35	\section{The classical low individual degree game}
  36	% Paper labels sec:ld-verifier and sec:ld-game kept for cross-reference fidelity.
  37	\label{sec:ld-verifier}
  38	\label{sec:ld-game}
  39	
  40	The classical low individual degree game is a two-player game based on the low individual degree variant of the multilinearity test of Babai, Fortnow, and Lund. In the basic version, one player (the ``points player'') receives a uniformly random point $u \in \F_q^m$ and answers with a value $a \in \F_q$, while the other player (the ``lines player'') receives a random line through $u$ --- either axis-parallel or diagonal --- and answers with a univariate polynomial describing the restriction of a global function to that line. If the players share a polynomial $g\colon \F_q^m \to \F_q$ of individual degree at most $d$ and answer with $g(u)$ and with the restriction $g|_\ell$, they win with probability $1$; the soundness theorem below states that the converse approximately holds. In the simultaneous version, the players' answers are $k$-tuples, checked coordinatewise against a $k$-tuple of low individual degree polynomials.
  41	
  42	\begin{definition}[The classical low individual degree game: parameters and registers]\label{def:ld-game}
  43		\lean{MIPStarRE.QPBT.ldGame}
  44		\leanok
  45		\uses{def:game, def:admissible-size}
  46		% The source fixes \N to be the set of positive integers
  47		% (references/qpbt-paper/04_preliminaries.tex:6) and takes m, d, ldc in \N
  48		% (references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:33-35),
  49		% so the positivity below is the source's implicit domain, stated explicitly.
  50		% It is load-bearing: at d = 0 or k = 0 the prefactor a(dmk)^a of delta_ld in
  51		% lem:ld-soundness vanishes, and at d = 0 the resulting exact conclusions fail
  52		% (e.g. at (q,m,d,k) = (2,1,0,1) with eps = 1). The case k = 0, though it would
  53		% hold trivially, is likewise outside the source's domain and is omitted.
  54		The game $\mathfrak{G}^{\mathrm{ld}}$ is parametrized by a tuple $\mathsf{ldparams} = (q,m,d,k)$, where $m, d, k \ge 1$ are integers, $q \in \N$ is an admissible field size (Definition~\ref{def:admissible-size}), and $m$ divides $q$. We write $\mathfrak{G}^{\mathrm{ld}}_{\mathsf{ldparams}}$ to emphasize the dependence on the parameter tuple. The type set of $\mathfrak{G}^{\mathrm{ld}}$ is
  55		\[
  56			\mathcal T^{\mathrm{ld}} = \{\mathsf{Point}, \mathsf{ALine}, \mathsf{DLine}\}\;,
  57		\]
  58		and the distribution over type pairs $(t_{\mathrm A}, t_{\mathrm B})$ is uniform over $\mathcal T^{\mathrm{ld}} \times \mathcal T^{\mathrm{ld}}$. The ambient space is the direct sum $V = V_X \oplus V_I \oplus V_V$ of three register subspaces: the \emph{point register} $V_X \cong \F_q^m$, the \emph{coordinate register} $V_I \cong \F_q$, and the \emph{direction register} $V_V \cong \F_q^m$. Elements of $V$ are identified with triples $(u,s,v) \in \F_q^m \times \F_q \times \F_q^m$. The question distribution and the win predicate of $\mathfrak{G}^{\mathrm{ld}}$ are specified in Definitions~\ref{def:ld-question-distribution} and~\ref{def:ld-win-predicate} below.
  59	\end{definition}
  60	
  61	\begin{definition}[Question distribution of the classical low individual degree game]\label{def:ld-question-distribution}
  62		\uses{def:ld-game, def:cl-func, def:cl-dist, lem:cl-concat, def:cl-canonical, def:line-representative}
  63		Let $\mathsf{ldparams} = (q,m,d,k)$ be as in Definition~\ref{def:ld-game}. Define $L_{\mathsf{Point}}$ to be the $1$-level CL function on $V$ that projects onto $V_X$: for every $(u,s,v) \in V$,
  64		\begin{equation}
  65			\label{eq:cl-ptf}
  66			L_{\mathsf{Point}}(u,s,v) = (u,0,0)\;.
  67		\end{equation}
  68		For $s \in \F_q$, let $\chi(s)$ be the unique integer such that
  69		\begin{equation}
  70			\label{eq:chi-func}
  71			s = (\chi(s)-1)\,\frac{q}{m} + r
  72		\end{equation}
  73		for some $0 \le r < q/m$, where $s$ is interpreted as an integer in $\{0,1,\ldots,q-1\}$ under the identification of $\F_q$ with binary strings fixed in Chapter~\ref{chap:qpbt-algebra}. Since $m$ divides $q$, when $s$ is uniformly distributed on $\F_q$ the index $\chi(s)$ is uniformly distributed on $\{1,2,\ldots,m\}$. Define $L_{\mathsf{ALine}}$ by
  74		\begin{equation}
  75			\label{eq:cl-alnf}
  76			L_{\mathsf{ALine}}(u,s,v) = \bigl(L^{\mathrm{Ln}}_{e_i}(u),\, s,\, 0\bigr)\quad\text{for all } (u,s,v) \in V\;,
  77		\end{equation}
  78		where $i = \chi(s)$ and $L^{\mathrm{Ln}}_v$ denotes the canonical linear map with one-dimensional kernel spanned by $v$, used to compute canonical representatives of lines (Definition~\ref{def:line-representative}). The function $L_{\mathsf{ALine}}$ is the concatenation (in the sense of Lemma~\ref{lem:cl-concat}) of the $1$-level CL function projecting $V_I \oplus V_V$ onto $V_I$ with the family of $1$-level CL functions $\{L^{\mathrm{Ln}}_{e_i}\}$ on $V_X$ indexed by $i \in \{1,\ldots,m\}$; thus $L_{\mathsf{ALine}}$ is a $2$-level CL function. Define $L_{\mathsf{DLine}}$ by
  79		\begin{equation}
  80			\label{eq:cl-dlnf}
  81			L_{\mathsf{DLine}}(u,s,v) = \bigl(L^{\mathrm{Ln}}_{\pi_{i-1}(v)}(u),\, s,\, \pi_{i-1}(v)\bigr)\;,
  82		\end{equation}
  83		where $i = \chi(s)$ and $\pi_{i-1}$ zeroes out the first $i-1$ coordinates of its input. The function $L_{\mathsf{DLine}}$ is the concatenation of (i) the identity on $V_I$, (ii) for each $i$ the $1$-level CL function $v \mapsto \pi_{i-1}(v)$ on $V_V$, and (iii) for each pair $(s,v') \in V_I \oplus V_V$ the $1$-level CL function $L^{\mathrm{Ln}}_{v'}$ on $V_X$; thus $L_{\mathsf{DLine}}$ is a $3$-level CL function.
  84	
  85		The question distribution of $\mathfrak{G}^{\mathrm{ld}}$ is the typed CL distribution obtained as follows: sample a type pair $(t_{\mathrm A}, t_{\mathrm B})$ uniformly from $\mathcal T^{\mathrm{ld}} \times \mathcal T^{\mathrm{ld}}$, sample $z = (u,s,v)$ uniformly from $V$, and send each player $w \in \{\mathrm A,\mathrm B\}$ the question $(t_w, L_{t_w}(z))$.
  86	\end{definition}
