  88	\begin{lemma}[Level of the point map]\label{lem:ld-point-level}
  89		\lean{MIPStarRE.QPBT.isCondLinear_ldPointCL}
  90		\leanok
  91		\uses{def:ld-question-distribution, def:cl-func}
  92		Fix $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game}. The map $L_{\mathsf{Point}}$ of Equation~\eqref{eq:cl-ptf} is a $1$-level conditionally linear function on $V$.
  93	\end{lemma}
  94	\begin{proof}
  95		\leanok
  96		\uses{def:ld-question-distribution, def:cl-func}
  97		The map $L_{\mathsf{Point}}$ is the linear projection onto the point register $V_X$, hence is a $1$-level CL function.
  98	\end{proof}
