 100	\begin{lemma}[Level of the axis-parallel line map]\label{lem:ld-aline-level}
 101		\lean{MIPStarRE.QPBT.isCondLinear_ldALineCL}
 102		\leanok
 103		\uses{def:ld-question-distribution, def:cl-func}
 104		Fix $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game}. The map $L_{\mathsf{ALine}}$ of Equation~\eqref{eq:cl-alnf} is a $2$-level conditionally linear function on $V$.
 105	\end{lemma}
 106	\begin{proof}
 107		\leanok
 108		\uses{def:cl-func, def:register-subspace, def:ld-question-distribution, def:line-representative}
 109		The following data exhibit $L_{\mathsf{ALine}}$ as a $2$-level conditionally linear function. Its first level is the projection of $V$ onto the coordinate register $V_I$, which is linear. For a first-level value with coordinate component $s$, its second level is the linear map $L^{\mathrm{Ln}}_{e_i}$ with $i = \chi(s)$, acting on the point register $V_X$. The registers $V_I$ and $V_X$ are disjoint, so the second level is supported on a register subspace disjoint from the first, and summing the two contributions gives $\bigl(L^{\mathrm{Ln}}_{e_i}(u),\, s,\, 0\bigr)$, which is $L_{\mathsf{ALine}}(u,s,v)$ by Equation~\eqref{eq:cl-alnf}.
 110	\end{proof}
