 112	\begin{lemma}[Level of the diagonal line map]\label{lem:ld-dline-level}
 113		\lean{MIPStarRE.QPBT.isCondLinear_ldDLineCL}
 114		\leanok
 115		\uses{def:ld-question-distribution, def:cl-func}
 116		Fix $\mathsf{ldparams} = (q,m,d,k)$ as in Definition~\ref{def:ld-game}. The map $L_{\mathsf{DLine}}$ of Equation~\eqref{eq:cl-dlnf} is a $3$-level conditionally linear function on $V$.
 117	\end{lemma}
 118	\begin{proof}
 119		\leanok
 120		\uses{def:cl-func, def:register-subspace, def:ld-question-distribution, def:line-representative}
 121		The following data exhibit $L_{\mathsf{DLine}}$ as a $3$-level conditionally linear function. Its first level is the projection of $V$ onto the coordinate register $V_I$. For a first-level value with coordinate component $s$, its second level is the linear map $v \mapsto \pi_{i-1}(v)$ with $i = \chi(s)$ on the direction register $V_V$. For a second-level value with direction component $v'$, its third level is the linear map $L^{\mathrm{Ln}}_{v'}$ on the point register $V_X$. The registers $V_I$, $V_V$ and $V_X$ are pairwise disjoint, so each level is supported on a register subspace disjoint from the preceding ones, and summing the three contributions gives $\bigl(L^{\mathrm{Ln}}_{\pi_{i-1}(v)}(u),\, s,\, \pi_{i-1}(v)\bigr)$, which is $L_{\mathsf{DLine}}(u,s,v)$ by Equation~\eqref{eq:cl-dlnf}.
 122	\end{proof}
