 503		Let $c, b \in \F_q^k$ with $c \neq b$.  Then
 504		\[
 505			\Pr_{\alpha \in \F_q^k}\Bigl[\; \sum_{r} c_r \alpha_r
 506				= \sum_{r} b_r \alpha_r \;\Bigr] \;\le\; \frac1q\;,
 507		\]
 508		the probability being over a uniformly random $\alpha$.
 509	\end{lemma}
 510	\begin{proof}
 511		\leanok
 512		\uses{lem:schwartz-zippel-total-degree}
 513		The two sides are the evaluations at $\alpha$ of the linear forms
 514		$\sum_r c_r X_r$ and $\sum_r b_r X_r$ in $k$ variables.  The coefficient of
 515		$X_r$ in such a form is $c_r$, so the two forms are distinct polynomials,
 516		and each has total degree at most $1$.  Lemma~\ref{lem:schwartz-zippel-total-degree}
 517		bounds the probability that two distinct polynomials of total degree at most
 518		$1$ agree at a uniformly random point of $\F_q^k$ by $1/q$.
 519	\end{proof}
