1595			\end{enumerate}
1596			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pauli},W)$, accept if $g_{a_{\overline w}}(x_w) = a_w$, where $g_{a_{\overline w}}$ is the low-degree encoding of $a_{\overline w} \in \F_q^M$ (Chapter~\ref{chap:qpbt-algebra}).
